def sont_semblables(A, B, C, D, E, F):
    import math
    def distance(P, Q):
        return math.hypot(P[0]-Q[0], P[1]-Q[1])
    cotes1 = sorted([distance(A,B), distance(B,C), distance(C,A)])
    cotes2 = sorted([distance(D,E), distance(E,F), distance(F,D)])
    r = cotes1[0] / cotes2[0]
    eps = 1e-9
    return abs(cotes1[1]/cotes2[1] - r) < eps and abs(cotes1[2]/cotes2[2] - r) < eps
